def verify_graph(edges, n=15):
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        assert 0 <= u < v < n, f"Invalid edge ({u}, {v})"
        adj[u].add(v)
        adj[v].add(u)

    # Check all vertices have degree >= 1
    for i in range(n):
        if len(adj[i]) < 1:
            print(f"Vertex {i} has degree 0")
            return False

    # Check no triangles (max clique size <= 2)
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        print(f"Triangle found: ({i}, {j}, {k})")
                        return False

    # Check chromatic number <= 4 using greedy coloring
    # Try to color with 4 colors
    colors = {}
    for i in range(n):
        used_colors = set()
        for j in adj[i]:
            if j in colors:
                used_colors.add(colors[j])
        for c in range(4):
            if c not in used_colors:
                colors[i] = c
                break
        else:
            print(f"Cannot color vertex {i} with 4 colors")
            return False

    print(f"Chromatic number <= 4: OK (used {max(colors.values())+1} colors)")
    print(f"Max clique size <= 2: OK (no triangles)")
    print(f"All degrees >= 1: OK")
    print(f"Number of edges: {len(edges)}")
    return True

# Fixed edges
fixed_edges = [(1,8), (1,9), (0,10), (0,6), (0,5)]

# Additional edges to ensure all vertices have degree >= 1
# Using bipartite structure: A = {0,1,2,3,4,7,11,12,13,14}, B = {5,6,8,9,10}
additional_edges = [
    (2, 5), (3, 6), (4, 8), (7, 9), (11, 10), (12, 5), (13, 6), (14, 8)
]

all_edges = fixed_edges + additional_edges
all_edges.sort()

print("Edges:", all_edges)
print()
result = verify_graph(all_edges)
print("\nResult:", "SATISFIABLE" if result else "UNSATISFIABLE")

